    private bool FactionUsesAttackerZone(
        string faction)
    {
        if (factions.Count < 2)
            return false;

        int factionIndex =
            faction == factions[0]
            ? 0
            : 1;

        return
            factionIndex ==
            missionAttackerIndex;
    }

    public void ClearUnusedArmedCommandRerollAfterAttack(
        string faction)
    {
        if (armedCommandRerollStage ==
                CommandRerollStage.None ||
            !string.Equals(
                armedCommandRerollFaction,
                faction,
                System.StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        // The attack had no failed roll at the armed stage. No CP was spent.
        ClearArmedCommandReroll();
    }

    private bool OfferFadeBackAfterAttack(
        InteractiveAttackController attack,
        System.Action after)
    {
        if (attack == null ||
            attack.Mode != AttackMode.Ranged ||
            attack.TotalHits <= 0 ||
            attack.Target == null ||
            !attack.Target.IsAlive ||
            attack.Target.HasKeyword("titanic") ||
            !CanUseBattleFocusManoeuvre(
                attack.Target))
        {
            return false;
        }

        SquadController unit =
            attack.Target.JoinedActionController();

        List<RuleChoiceOption> options =
            new List<RuleChoiceOption>();

        options.Add(
            new RuleChoiceOption(
                "Fade Back (1 BF)",
                () =>
                {
                    CloseRuleChoice();

                    if (!SpendBattleFocusFor(
                            unit,
                            "FADE BACK"))
                    {
                        if (after != null)
                            after();
                        return;
                    }

                    if (!IsXcomMode)
                    {
                        OpenTraditionalNumericPrompt(
                            "FADE BACK",
                            unit.DisplayName +
                            " makes a D6+1 Normal move. Resolve the roll/rerolls yourself and enter the final distance.",
                            2 +
                                (aeldariRules != null
                                    ? aeldariRules.AgileD6Bonus(
                                        unit.FactionId)
                                    : 0),
                            7 +
                                (aeldariRules != null
                                    ? aeldariRules.AgileD6Bonus(
                                        unit.FactionId)
                                    : 0),
                            2 +
                                (aeldariRules != null
                                    ? aeldariRules.AgileD6Bonus(
                                        unit.FactionId)
                                    : 0),
                            1,
                            value =>
                                BeginSpecialMove(
                                    unit,
                                    value,
                                    "Fade Back",
                                    after
                                ),
                            after
                        );

                        return;
                    }

                    int move =
                        DiceRoller.RollD6(
                            "Fade Back: " +
                            unit.DisplayName
                        ) +
                        1 +
                        (aeldariRules != null
                            ? aeldariRules
                                .AgileD6Bonus(
                                    unit.FactionId
                                )
                            : 0);

                    BeginSpecialMove(
                        unit,
                        move,
                        "Fade Back",
                        after
                    );
                }
            )
        );

        if (UsesDevotedOfYnneadRules(
                unit.FactionId) &&
            unit.HasKeyword("ynnari") &&
            factionRules.CanUseLethalSurge(
                unit.FactionId))
        {
            options.Add(
                new RuleChoiceOption(
                    "Lethal Surge via Fade Back (1 BF)",
                    () =>
                    {
                        CloseRuleChoice();

                        if (!SpendBattleFocusFor(
                                unit,
                                "FADE BACK  -  LETHAL SURGE"))
                        {
                            if (after != null)
                                after();
                            return;
                        }

                        factionRules.MarkLethalSurgeUsed(
                            unit.FactionId
                        );

                        if (!IsXcomMode)
                        {
                            OpenTraditionalNumericPrompt(
                                "LETHAL SURGE",
                                unit.DisplayName +
                                " makes a D6+1 Surge move. Resolve the roll yourself and enter the final distance.",
                                2 +
                                    (aeldariRules != null
                                        ? aeldariRules.AgileD6Bonus(
                                            unit.FactionId)
                                        : 0),
                                7 +
                                    (aeldariRules != null
                                        ? aeldariRules.AgileD6Bonus(
                                            unit.FactionId)
                                        : 0),
                                2 +
                                    (aeldariRules != null
                                        ? aeldariRules.AgileD6Bonus(
                                            unit.FactionId)
                                        : 0),
                                1,
                                value =>
                                    BeginSurgeMove(
                                        unit,
                                        value,
                                        "Lethal Surge",
                                        after
                                    ),
                                after
                            );

                            return;
                        }

                        int move =
                            DiceRoller.RollD6(
                                "Lethal Surge: " +
                                unit.DisplayName
                            ) +
                            1 +
                            (aeldariRules != null
                                ? aeldariRules
                                    .AgileD6Bonus(
                                        unit.FactionId
                                    )
                                : 0);

                        BeginSurgeMove(
                            unit,
                            move,
                            "Lethal Surge",
                            after
                        );
                    }
                )
            );
        }

        options.Add(
            new RuleChoiceOption(
                "Do not Fade Back",
                () =>
                {
                    CloseRuleChoice();
                    if (after != null)
                        after();
                }
            )
        );

        OpenRuleChoice(
            "BATTLE FOCUS  -  FADE BACK",
            unit.DisplayName +
            " was hit by ranged attacks. Spend 1 Battle Focus token to make a D6+1 Normal move.",
            options
        );

        return true;
    }

