    private void BeginSpecialShoot(
        SquadController shooter,
        SquadController forcedTarget,
        string label,
        System.Action onComplete)
    {
        if (shooter == null ||
            !shooter.IsAlive ||
            !shooter.IsOnBattlefield)
        {
            if (onComplete != null)
                onComplete();

            return;
        }

        specialShootUnit =
            shooter.JoinedActionController();

        specialShootForcedTarget =
            forcedTarget != null
            ? forcedTarget.JoinedActionController()
            : null;

        specialShootLabel =
            label ??
            "Special Shooting";

        specialShootCompleted =
            onComplete;

        if (specialShootForcedTarget != null)
        {
            TryCompleteSpecialShoot(
                specialShootForcedTarget
            );
            return;
        }

        status =
            specialShootLabel +
            ": click an eligible enemy target for " +
            specialShootUnit.DisplayName +
            ".";
    }

    private void TryCompleteSpecialShoot(
        SquadController target)
    {
        if (specialShootUnit == null ||
            target == null ||
            !target.IsAlive ||
            !target.IsOnBattlefield ||
            target.FactionId ==
                specialShootUnit.FactionId)
        {
            return;
        }

        if (specialShootForcedTarget != null &&
            target.JoinedActionController() !=
                specialShootForcedTarget)
        {
            status =
                specialShootLabel +
                " must target " +
                specialShootForcedTarget.DisplayName +
                ".";
            return;
        }

        SquadController shooter =
            specialShootUnit;

        bool engaged =
            IsEngaged(shooter);

        List<WeaponAttackSelection> weapons =
            GetEligibleRangedWeapons(
                shooter,
                target,
                engaged
            );

        if (weapons.Count == 0)
        {
            status =
                specialShootLabel +
                ": no eligible ranged weapons can target " +
                target.DisplayName +
                ".";
            return;
        }

        System.Action callback =
            specialShootCompleted;

        specialShootUnit = null;
        specialShootForcedTarget = null;
        specialShootLabel = "";
        specialShootCompleted = null;

        interactiveAttackCompletionCallback =
            callback;

        interactiveAttackConsumesNormalAction =
            false;
        interactiveAttackSuppressesPostReactions =
            true;

        BeginInteractiveAttack(
            shooter,
            target,
            weapons,
            AttackMode.Ranged,
            engaged
        );
    }

    private void BeginInteractiveAttack(
        SquadController attacker,
        SquadController target,
        List<WeaponAttackSelection> selections,
        AttackMode attackMode,
        bool engagedShooting)
    {
        if (interactiveAttack != null)
        {
            status =
                "Another attack is already being resolved.";
            return;
        }

        ClearArmedCommandReroll();

        GameEventBus.Raise(
            new GameEventContext
            {
                Type =
                    GameEventType.AttackStarted,
                Game = this,
                ActingFaction =
                    attacker.FactionId,
                Phase = phase,
                Source = attacker,
                Target = target,
                AttackMode =
                    attackMode
            }
        );

        if (!IsXcomMode)
        {
            BeginTraditionalAttackDeclaration(
                attacker,
                target,
                selections,
                attackMode,
                engagedShooting
            );

            return;
        }

        interactiveAttack =
            new InteractiveAttackController(
                this,
                attacker,
                target,
                selections,
                attackMode
            );

        status =
            attacker.DisplayName +
            " attacks " +
            target.DisplayName +
            (IsXcomMode
                ? ". XCOM resolution running."
                : ". Resolve the dice popup stage by stage.") +
            (engagedShooting
                ? " PISTOLS ONLY."
                : "");

        if (IsXcomMode)
        {
            ResumeXcomAttack();
        }
    }

    private void ResumeXcomAttack()
    {
        if (interactiveAttack == null)
            return;

        bool completed =
            interactiveAttack
                .FastResolveUntilDecision();

        if (completed)
        {
            FinalizeInteractiveAttack();
            return;
        }

        status =
            "XCOM RESOLUTION PAUSED  -  decision required: " +
            interactiveAttack.StageTitle +
            ".";
    }

    private void StartPostAttackFlow(
        InteractiveAttackController resolvedAttack,
        System.Action finalizer)
    {
        postAttackFlowQueue.Clear();
        postAttackFinalizer = finalizer;

        if (resolvedAttack == null)
        {
            ContinuePostAttackFlow();
            return;
        }

        if (resolvedAttack.Mode ==
            AttackMode.Melee)
        {
            postAttackFlowQueue.Enqueue(
                () =>
                    OfferFightOnDeath(
                        resolvedAttack
                    )
            );
        }

        postAttackFlowQueue.Enqueue(
            () =>
                OfferUndyingLegions(
                    resolvedAttack
                )
        );

        postAttackFlowQueue.Enqueue(
            () =>
                OfferVengefulStars(
                    resolvedAttack
                )
        );

        postAttackFlowQueue.Enqueue(
            () =>
                OfferPallOfDread(
                    resolvedAttack
                )
        );

        postAttackFlowQueue.Enqueue(
            () =>
                ResolveStormOfWhispers(
                    resolvedAttack
                )
        );

        if (resolvedAttack.Mode ==
            AttackMode.Ranged)
        {
            postAttackFlowQueue.Enqueue(
                () =>
                {
                    if (!OfferFadeBackAfterAttack(
                            resolvedAttack,
                            ContinuePostAttackFlow))
                    {
                        ContinuePostAttackFlow();
                    }
                }
            );
        }

        ContinuePostAttackFlow();
    }

    private void ContinuePostAttackFlow()
    {
        if (showRuleChoiceWindow ||
            specialMoveSquad != null ||
            specialShootUnit != null ||
            interactiveAttack != null)
        {
            return;
        }

        if (postAttackFlowQueue.Count > 0)
        {
            System.Action next =
                postAttackFlowQueue.Dequeue();

            next();
            return;
        }

        System.Action finalizer =
            postAttackFinalizer;

        postAttackFinalizer = null;

        if (finalizer != null)
            finalizer();
    }

    private void FinalizeInteractiveAttack()
    {
        if (interactiveAttack == null ||
            !interactiveAttack.IsComplete)
        {
            return;
        }

        if (interactiveAttack
            .HasPendingCasualtyChoices)
        {
            pendingCasualtyCandidate = null;
            pendingCasualtyCoherencyWarning = false;

            InteractiveCasualtyChoice choice =
                interactiveAttack
                    .CurrentPendingCasualty;

            status =
                "CASUALTY SELECTION: " +
                (choice != null
                    ? choice.Label
                    : "model") +
                " was destroyed. Click the model you want to remove, or keep the automatic casualty.";

            return;
        }

        InteractiveAttackController resolvedAttack =
            interactiveAttack;

        SquadController attacker =
            resolvedAttack.Attacker;

        SquadController target =
            resolvedAttack.Target;

        AttackMode attackMode =
            resolvedAttack.Mode;

        int woundsLost =
            resolvedAttack.TotalWoundsLost;

        if (attackMode ==
            AttackMode.Ranged)
        {
            resolvedAttack.MarkOneShotWeaponsUsed();

            if (interactiveAttackModelLevelShooting)
            {
                resolvedAttack
                    .MarkRangedWeaponsFiredThisTurn();
            }
        }

        bool modelLevelShooting =
            interactiveAttackModelLevelShooting;

        bool consumeNormalAction =
            interactiveAttackConsumesNormalAction;

        bool suppressPostReactions =
            interactiveAttackSuppressesPostReactions;

        System.Action completionCallback =
            interactiveAttackCompletionCallback;

        interactiveAttack = null;
        interactiveAttackCompletionCallback = null;
        interactiveAttackConsumesNormalAction = true;
        interactiveAttackSuppressesPostReactions = false;
        interactiveAttackModelLevelShooting = false;

        GameEventBus.Raise(
            new GameEventContext
            {
                Type =
                    GameEventType.AttackResolved,
                Game = this,
                ActingFaction =
                    attacker != null
                    ? attacker.FactionId
                    : activeFaction,
                Phase = phase,
                Source = attacker,
                Target = target,
                AttackMode =
                    attackMode,
                Amount =
                    woundsLost
            }
        );

        if (consumeNormalAction &&
            attacker != null)
        {
            if (attackMode ==
                AttackMode.Ranged)
            {
                attacker.HasShot = true;
                NotifyUnitFinishedShooting(attacker);

                if (attacker.AttachedLeader != null)
                    attacker.AttachedLeader.HasShot = true;
            }
            else
            {
                attacker.HasFought = true;

                if (attacker.AttachedLeader != null)
                    attacker.AttachedLeader.HasFought = true;
            }
        }

        if (modelLevelShooting &&
            attacker != null)
        {
            RefreshModelLevelShootingState(
                attacker
            );
        }

        HandleBodyguardDestroyed(target);
        HandleBodyguardDestroyed(attacker);
        RefreshObjectiveDisplays();

        if (target != null &&
            !target.IsAlive &&
            (target.AttachedLeader == null ||
             !target.AttachedLeader.IsAlive))
        {
            GameEventBus.Raise(
                new GameEventContext
                {
                    Type =
                        GameEventType.UnitDestroyed,
                    Game = this,
                    ActingFaction =
                        attacker != null
                        ? attacker.FactionId
                        : activeFaction,
                    Phase = phase,
                    Source = attacker,
                    Target = target,
                    AttackMode =
                        attackMode
                }
            );
        }

        System.Action finalizer =
            () =>
            {
                if (attackMode ==
                        AttackMode.Melee &&
                    attacker != null &&
                    attacker.IsAlive &&
                    consumeNormalAction)
                {
                    SquadController consolidationTarget =
                        FindNearestEnemy(attacker);

                    if (consolidationTarget != null)
                    {
                        AutoMoveSquadToward(
                            attacker,
                            consolidationTarget,
                            attacker.SuddenStrikeActive
                                ? 6f
                                : ConsolidateDistance,
                            0.86f
                        );
                    }

                    attacker.KatahSustainedActive = false;
                    attacker.KatahLethalActive = false;

                    AdvanceFightPriority(
                        attacker
                    );
                }

                AppendBattleLog(
                    attackMode ==
                        AttackMode.Ranged
                    ? "SHOOTING"
                    : "MELEE",
                    resolvedAttack.SummaryText(),
                    resolvedAttack.AuditText()
                );

                status =
                    resolvedAttack.SummaryText() +
                    (attackMode ==
                        AttackMode.Melee &&
                     consumeNormalAction
                        ? " Consolidation resolved."
                        : "");

                if (completionCallback != null)
                    completionCallback();
            };

        if (suppressPostReactions)
        {
            finalizer();
        }
        else
        {
            StartPostAttackFlow(
                resolvedAttack,
                finalizer
            );
        }
    }

    private bool CasualtyCandidateIsValid(
        ModelToken candidate)
    {
        if (interactiveAttack == null ||
            candidate == null ||
            !candidate.IsAlive)
        {
            return false;
        }

        InteractiveCasualtyChoice choice =
            interactiveAttack
                .CurrentPendingCasualty;

        if (choice == null ||
            choice.automaticModel == null ||
            choice.automaticModel.Squad == null ||
            candidate.Squad == null)
        {
            return false;
        }

        return
            candidate.Squad ==
            choice.automaticModel.Squad;
    }

    private void TryChooseAttackCasualty(
        ModelToken candidate)
    {
        if (!CasualtyCandidateIsValid(
                candidate))
        {
            status =
                "That model is not a legal replacement casualty for this destroyed model.";
            return;
        }

        SquadController actionUnit =
            candidate.Squad
                .JoinedActionController();

        bool coherent =
            actionUnit
                .WouldRemainCoherentAfterRemoving(
                    candidate
                );

        if (!coherent)
        {
            pendingCasualtyCandidate =
                candidate;

            pendingCasualtyCoherencyWarning =
                true;

            status =
                "COHERENCY WARNING: removing " +
                candidate.RoleName +
                " will leave the unit out of coherency. Confirm REMOVE ANYWAY or choose another model.";

            return;
        }

        ConfirmAttackCasualty(
            candidate
        );
    }

    private void ConfirmAttackCasualty(
        ModelToken candidate)
    {
        if (interactiveAttack == null ||
            !interactiveAttack
                .HasPendingCasualtyChoices)
        {
            return;
        }

        ModelToken casualty =
            interactiveAttack
                .ConfirmNextCasualty(
                    candidate
                );

        if (casualty != null)
        {
            AppendBattleLog(
                "CASUALTY",
                casualty.Squad != null
                ? casualty.Squad.DisplayName
                : "Unit",
                casualty.RoleName +
                " removed by player casualty selection."
            );
        }

        pendingCasualtyCandidate = null;
        pendingCasualtyCoherencyWarning = false;

        if (interactiveAttack
            .HasPendingCasualtyChoices)
        {
            InteractiveCasualtyChoice next =
                interactiveAttack
                    .CurrentPendingCasualty;

            status =
                "CASUALTY SELECTED: " +
                (casualty != null
                    ? casualty.RoleName
                    : "model") +
                ". Select the next casualty (" +
                interactiveAttack
                    .PendingCasualtyCount +
                " remaining)." +
                (next != null
                    ? " Automatic suggestion: " +
                      next.Label +
                      "."
                    : "");

            return;
        }

        int coherencyLosses =
            ResolveForcedCoherencyLosses(
                interactiveAttack.Target,
                interactiveAttack.Attacker
            );

        if (coherencyLosses > 0)
        {
            status =
                coherencyLosses +
                " additional model(s) were removed because the unit remained out of coherency.";
        }

        FinalizeInteractiveAttack();
    }

    private bool TargetHasLoneOperativeProtection(
        SquadController target)
    {
        if (target == null)
            return false;

        SquadController unit =
            target.JoinedActionController();

        if (FactionRuleSystem.UnitOrLeaderHasRule(
                unit,
                "Lone Operative"))
        {
            return true;
        }

        bool spiritseer =
            UniversalRuleRegistry.UnitHasRule(
                unit,
                "Spiritseer"
            ) ||
            unit.DisplayName.IndexOf(
                "Spiritseer",
                System.StringComparison.OrdinalIgnoreCase
            ) >= 0;

        if (!spiritseer)
            return false;

        return squads.Any(
            wraith =>
                wraith != null &&
                wraith.IsAlive &&
                wraith.IsOnBattlefield &&
                wraith.FactionId ==
                    unit.FactionId &&
                wraith.HasKeyword(
                    "wraith construct") &&
                JoinedDistance(
                    unit,
                    wraith
                ) <= 3.001f
        );
    }

    private void TryShoot(
        SquadController attacker,
        SquadController target)
    {
        string necronsTargetReason;
        if (attacker != null && target != null &&
            !Necrons11CanAttackTarget(
                attacker, target, AttackMode.Ranged,
                out necronsTargetReason))
        {
            status = necronsTargetReason;
            return;
        }

        if (attacker != null &&
            !Necrons11EnsureCryptekAugmentation(attacker))
        {
            return;
        }


        string custodesTargetReason;
        if (attacker != null && target != null &&
            !Custodes11CanAttackTarget(
                attacker, target, AttackMode.Ranged,
                out custodesTargetReason))
        {
            status = custodesTargetReason;
            return;
        }


        if (missionSystem != null &&
            missionSystem.UnitHasStartedAction(
                attacker) &&
            !attacker.HasKeyword(
                "titanic"))
        {
            status =
                "That unit started a mission action this turn and cannot shoot.";
            return;
        }

        if (attacker.HasShot)
        {
            status =
                "That squad has already shot.";
            return;
        }

        if (attacker.HasFallenBack &&
            !Necrons11CanShootAfterFallBack(attacker) &&
            !Custodes11CanShootAfterFallBack(attacker) &&
            !(aeldariRules != null &&
              aeldariRules.CanShootAfterFallBack(
                  attacker
              )))
        {
            status =
                "That squad Fell Back this turn and cannot shoot.";
            return;
        }

        if (aeldariRules != null &&
            aeldariRules.HasRange18Protection(
                target) &&
            JoinedDistance(
                attacker,
                target
            ) > 18.001f)
        {
            status =
                target.DisplayName +
                " cannot be selected as a ranged target from more than 18 inches away.";
            return;
        }

        if (TargetHasLoneOperativeProtection(
                target) &&
            JoinedDistance(
                attacker,
                target
            ) > 12.001f)
        {
            status =
                target.DisplayName +
                " has Lone Operative protection and cannot be targeted from more than 12 inches away.";
            return;
        }

        bool engaged =
            IsEngaged(attacker);

        bool attackerBig =
            attacker.HasKeyword("monster") ||
            attacker.HasKeyword("vehicle");

        bool targetEngaged =
            IsEngaged(target);

        bool targetBig =
            target.HasKeyword("monster") ||
            target.HasKeyword("vehicle");

        bool engagedTogether =
            UnitsAreEngaged(
                attacker,
                target
            );

        if (engaged &&
            !attackerBig &&
            !engagedTogether)
        {
            status =
                "An engaged non-Monster/Vehicle unit can only use Close-Quarters/Pistol weapons against an enemy it is engaged with.";
            return;
        }

        if (targetEngaged &&
            !targetBig &&
            !engagedTogether)
        {
            status =
                "That target is engaged and is not a Monster/Vehicle, so it cannot be selected for this ranged attack.";
            return;
        }

        if (selectedModel == null ||
            selectedModel.Squad == null ||
            selectedModel.Squad
                .JoinedActionController() !=
                attacker.JoinedActionController())
        {
            status =
                "SHOOTING: click the specific model that will fire, then click its target.";
            return;
        }

        List<WeaponAttackSelection> eligibleWeapons =
            GetEligibleRangedWeapons(
                attacker,
                target,
                engaged
            )
            .Where(
                selection =>
                    selection != null &&
                    selection.model ==
                        selectedModel
            )
            .ToList();

        if (eligibleWeapons.Count == 0)
        {
            status =
                selectedModel.RoleName +
                " has no unused ranged weapon with legal range/line of sight to " +
                target.DisplayName +
                ".";
            return;
        }

        OpenModelWeaponChoice(
            attacker,
            selectedModel,
            target,
            eligibleWeapons,
            engaged
        );
    }

    private void OpenModelWeaponChoice(
        SquadController attacker,
        ModelToken firingModel,
        SquadController target,
        List<WeaponAttackSelection> choices,
        bool engaged)
    {
        if (attacker == null ||
            firingModel == null ||
            target == null ||
            choices == null ||
            choices.Count == 0)
        {
            return;
        }

        List<WeaponAttackSelection> distinct =
            choices
                .GroupBy(
                    selection =>
                        !string.IsNullOrWhiteSpace(
                            selection.weapon.id)
                        ? selection.weapon.id
                        : selection.weapon.displayName
                )
                .Select(
                    group =>
                        group.First()
                )
                .ToList();

        if (distinct.Count == 1)
        {
            StartModelWeaponAttack(
                attacker,
                firingModel,
                target,
                distinct[0],
                engaged
            );

            return;
        }

        List<RuleChoiceOption> options =
            new List<RuleChoiceOption>();

        foreach (WeaponAttackSelection choice
            in distinct)
        {
            WeaponAttackSelection captured =
                choice;

            WeaponData weapon =
                captured.weapon;

            string profile =
                weapon.displayName +
                "   |   " +
                weapon.range.ToString("0.#") +
                "\"  A " +
                (string.IsNullOrWhiteSpace(
                    weapon.attacksExpression)
                    ? weapon.attacksPerModel
                        .ToString()
                    : weapon.attacksExpression) +
                "  S " +
                weapon.strength +
                "  AP " +
                weapon.ap;

            options.Add(
                new RuleChoiceOption(
                    profile,
                    () =>
                    {
                        CloseRuleChoice();

                        StartModelWeaponAttack(
                            attacker,
                            firingModel,
                            target,
                            captured,
                            engaged
                        );
                    }
                )
            );
        }

        OpenRuleChoice(
            "SELECT WEAPON  -  " +
            firingModel.RoleName,
            "Choose which weapon this model will fire at " +
            target.DisplayName +
            ". After it resolves, select the model again to fire another unused compatible weapon, or mark the model/unit done shooting.",
            options.ToArray()
        );
    }

    private void StartModelWeaponAttack(
        SquadController attacker,
        ModelToken firingModel,
        SquadController target,
        WeaponAttackSelection choice,
        bool engaged)
    {
        if (choice == null ||
            choice.weapon == null ||
            choice.model !=
                firingModel)
        {
            return;
        }

        if (OfferAeldariPathOfWarrior(
                attacker,
                () =>
                    StartModelWeaponAttack(
                        attacker,
                        firingModel,
                        target,
                        choice,
                        engaged
                    )))
        {
            return;
        }

        interactiveAttackConsumesNormalAction = false;
        interactiveAttackModelLevelShooting = true;

        BeginInteractiveAttack(
            attacker,
            target,
            new List<WeaponAttackSelection>
            {
                choice
            },
            AttackMode.Ranged,
            engaged
        );
    }

    private void RefreshModelLevelShootingState(
        SquadController attacker)
    {
        if (attacker == null)
            return;

        SquadController actionUnit =
            attacker.JoinedActionController();

        List<ModelToken> firingModels =
            JoinedModels(
                actionUnit
            )
            .Where(
                model =>
                    model != null &&
                    model.IsAlive &&
                    model.RangedWeapons.Count > 0
            )
            .ToList();

        bool finished =
            firingModels.Count == 0 ||
            firingModels.All(
                model =>
                    model
                        .HasCompletedShootingThisTurn
            );

        actionUnit.HasShot =
            finished;

        if (actionUnit.AttachedLeader != null)
        {
            actionUnit.AttachedLeader.HasShot =
                finished;
        }

        if (finished)
        {
            status =
                actionUnit.DisplayName +
                " has finished shooting.";
        }
    }

    private void CompleteSelectedModelShooting()
    {
        if (selectedModel == null)
            return;

        selectedModel
            .CompleteShootingThisTurn();

        RefreshModelLevelShootingState(
            selectedSquad
        );

        status =
            selectedModel.RoleName +
            " marked DONE shooting.";
    }

    private void CompleteSelectedUnitShooting()
    {
        if (selectedSquad == null)
            return;

        foreach (ModelToken model
            in JoinedModels(
                selectedSquad))
        {
            if (model != null &&
                model.IsAlive)
            {
                model
                    .CompleteShootingThisTurn();
            }
        }

        selectedSquad.HasShot = true;

        NotifyUnitFinishedShooting(selectedSquad);

        if (selectedSquad.AttachedLeader != null)
        {
            selectedSquad.AttachedLeader.HasShot = true;
        }

        status =
            selectedSquad.DisplayName +
            " marked DONE shooting.";
    }

    private List<WeaponAttackSelection>
        GetEligibleRangedWeapons(
            SquadController attacker,
            SquadController target,
            bool attackerEngaged)
    {
        List<WeaponAttackSelection> result =
            new List<WeaponAttackSelection>();

        if (missionSystem != null &&
            missionSystem.UnitHasStartedAction(
                attacker) &&
            !attacker.HasKeyword(
                "titanic"))
        {
            return result;
        }

        bool attackerBig =
            attacker.HasKeyword("monster") ||
            attacker.HasKeyword("vehicle");

        bool targetEngaged =
            IsEngaged(target);

        bool targetBig =
            target.HasKeyword("monster") ||
            target.HasKeyword("vehicle");

        bool engagedTogether =
            UnitsAreEngaged(
                attacker,
                target
            );

        foreach (ModelToken model
            in JoinedModels(attacker))
        {
            List<WeaponData> eligible =
                new List<WeaponData>();

            foreach (WeaponData weapon
                in model.RangedWeapons)
            {
                if (weapon == null ||
                    !model.CanUseWeapon(
                        weapon) ||
                    !model.CanFireRangedWeaponThisTurn(
                        weapon))
                {
                    continue;
                }

                bool closeQuarters =
                    RulesEngine.HasKeyword(
                        weapon,
                        "pistol"
                    ) ||
                    WeaponRuleParser.Has(
                        weapon,
                        "close_quarters"
                    );

                bool indirect =
                    WeaponRuleParser.Has(
                        weapon,
                        "indirect_fire"
                    );

                bool blast =
                    WeaponRuleParser.Has(
                        weapon,
                        "blast"
                    );

                if (attacker.HasAdvanced &&
                    !Necrons11CanShootAfterAdvance(attacker) &&
                    !Custodes11CanShootAfterAdvance(attacker) &&
                    !attacker
                        .JoinedActionController()
                        .SnapShootingActive &&
                    !WeaponRuleParser.Has(
                        weapon,
                        "assault") &&
                    !attacker
                        .JoinedActionController()
                        .FactionSuddenStormActive &&
                    !attacker
                        .JoinedActionController()
                        .StarEnginesActive &&
                    !(aeldariRules != null &&
                      aeldariRules
                        .VehicleRangedHasAssault(
                            attacker
                        )))
                {
                    continue;
                }

                if (attackerEngaged &&
                    !attackerBig)
                {
                    if (!closeQuarters ||
                        !engagedTogether)
                    {
                        continue;
                    }
                }

                if (attackerBig &&
                    attackerEngaged &&
                    blast &&
                    targetEngaged)
                {
                    continue;
                }

                if (targetEngaged &&
                    !targetBig &&
                    !engagedTogether)
                {
                    continue;
                }

                float distance =
                    ModelDistanceToSquad(
                        model,
                        target
                    );

                float effectiveRange =
                    weapon.range +
                    AeldariRangedRangeModifier(
                        attacker,
                        weapon
                    );

                if (distance >
                    effectiveRange +
                    0.001f)
                {
                    continue;
                }

                bool visible =
                    ModelHasLineOfSight(
                        model,
                        target
                    );

                if (!visible)
                {
                    bool legalIndirect =
                        indirect &&
                        !attackerEngaged &&
                        !attacker.HasAdvanced &&
                    !Necrons11CanShootAfterAdvance(attacker) &&
                    !Custodes11CanShootAfterAdvance(attacker) &&
                        !targetEngaged;

                    if (!legalIndirect)
                        continue;
                }

                eligible.Add(weapon);
            }

            if (eligible.Count == 0)
                continue;

            if (attackerEngaged &&
                !attackerBig)
            {
                foreach (WeaponData weapon
                    in eligible)
                {
                    result.Add(
                        new WeaponAttackSelection(
                            model,
                            weapon
                        )
                    );
                }

                continue;
            }

            bool hasNonCloseQuarters =
                eligible.Any(
                    weapon =>
                        !RulesEngine.HasKeyword(
                            weapon,
                            "pistol"
                        ) &&
                        !WeaponRuleParser.Has(
                            weapon,
                            "close_quarters"
                        )
                );

            foreach (WeaponData weapon
                in eligible)
            {
                bool closeQuarters =
                    RulesEngine.HasKeyword(
                        weapon,
                        "pistol"
                    ) ||
                    WeaponRuleParser.Has(
                        weapon,
                        "close_quarters"
                    );

                // Outside engagement, do not mix Close-Quarters/Pistol
                // weapons with other ranged weapons.
                if (!attackerEngaged &&
                    hasNonCloseQuarters &&
                    closeQuarters)
                {
                    continue;
                }

                result.Add(
                    new WeaponAttackSelection(
                        model,
                        weapon
                    )
                );
            }
        }

        return result;
    }

    private float DistanceSquadToTargetAfterTranslation(
        SquadController attacker,
        SquadController target,
        Vector3 delta)
    {
        float best =
            float.MaxValue;

        foreach (ModelToken attackerModel
            in JoinedModels(attacker))
        {
            Vector3 translated =
                attackerModel.transform.position +
                delta;

            foreach (ModelToken targetModel
                in JoinedModels(target))
            {
                best =
                    Mathf.Min(
                        best,
                        HorizontalDistance(
                            translated,
                            targetModel.transform.position
                        )
                    );
            }
        }

        return best ==
            float.MaxValue
            ? 999f
            : best;
    }

    private bool IsEngagedWithNonTargetEnemy(
        SquadController attacker,
        SquadController target)
    {
        foreach (SquadController other
            in squads)
        {
            if (other == target ||
                other.IsAttachedLeader ||
                other.FactionId ==
                    attacker.FactionId ||
                !other.IsAlive)
            {
                continue;
            }

            if (JoinedDistance(
                    attacker,
                    other
                ) <=
                EngagementRange + 0.05f)
            {
                return true;
            }
        }

        return false;
    }

    public bool FriendlyUnitCanSeeTarget(
        string faction,
        SquadController target)
    {
        if (target == null)
            return false;

        foreach (SquadController squad
            in squads)
        {
            if (squad == null ||
                !squad.IsAlive ||
                !squad.IsOnBattlefield ||
                squad.FactionId !=
                    faction)
            {
                continue;
            }

            foreach (ModelToken model
                in JoinedModels(squad))
            {
                if (ModelHasLineOfSight(
                    model,
                    target))
                {
                    return true;
                }
            }
        }

        return false;
    }

    public bool TargetUnitHasCoverFromShooter(
        ModelToken shooter,
        SquadController target)
    {
        return Core11TargetUnitHasCoverFromShooter(shooter, target);
    }

    public bool TargetModelHasCoverFromShooter(
        ModelToken shooter,
        ModelToken targetModel)
    {
        return Core11TargetModelHasCoverFromShooter(shooter, targetModel);
    }

    public int ApplyMortalWounds(
        SquadController target,
        int mortalWounds,
        string label)
    {
        if (target == null ||
            mortalWounds <= 0)
        {
            return 0;
        }

        int remaining =
            mortalWounds;

        int lostTotal = 0;

        while (remaining > 0 &&
               target.IsAlive)
        {
            ModelToken model =
                target.GetAutomaticAllocationModel();

            if (model == null &&
                target.AttachedLeader != null)
            {
                model =
                    target.AttachedLeader
                        .GetAutomaticAllocationModel();
            }

            if (model == null)
                break;

            int one =
                UniversalRuleRegistry
                    .ApplyFeelNoPain(
                        model.Squad,
                        1,
                        label
                    );

            if (one > 0)
            {
                bool wasAlive =
                    model.IsAlive;

                int lost =
                    model.ApplyDamage(1);

                lostTotal += lost;

                if (wasAlive &&
                    !model.IsAlive)
                {
                    ResolveDeadlyDemise(
                        model
                    );
                }
            }

            remaining--;
        }

        return lostTotal;
    }

}
